package solution

import (
	"math"
	"reflect"
	"testing"
)

func TestInterpolateObservationExactAndInterpolated(t *testing.T) {
	observations := []Observation{{Minute: 0, Value: -10}, {Minute: 10, Value: 10}, {Minute: 30, Value: 20}}
	original := append([]Observation(nil), observations...)
	cases := []struct {
		minute int
		want   float64
	}{
		{0, -10},
		{10, 10},
		{20, 15},
		{30, 20},
	}
	for _, tc := range cases {
		got, err := InterpolateObservation(observations, tc.minute)
		if err != nil || got != tc.want {
			t.Fatalf("minute %d = %v, %v; want %v, nil", tc.minute, got, err, tc.want)
		}
	}
	if !reflect.DeepEqual(observations, original) {
		t.Fatalf("input mutated: %#v", observations)
	}
}

func TestInterpolateObservationMinuteBoundaries(t *testing.T) {
	observations := []Observation{{Minute: 0, Value: 1}, {Minute: 1439, Value: 3}}
	for _, minute := range []int{0, 1439} {
		if _, err := InterpolateObservation(observations, minute); err != nil {
			t.Fatalf("valid boundary minute %d rejected: %v", minute, err)
		}
	}
	for _, minute := range []int{-1, 1440} {
		if got, err := InterpolateObservation(observations, minute); err == nil || got != 0 {
			t.Fatalf("invalid requested minute %d = %v, %v", minute, got, err)
		}
	}
}

func TestInterpolateObservationRejectsInvalidInput(t *testing.T) {
	cases := []struct {
		name string
		in   []Observation
		at   int
	}{
		{"nil", nil, 0},
		{"too few", []Observation{{Minute: 1, Value: 2}}, 1},
		{"minute below range", []Observation{{Minute: -1, Value: 1}, {Minute: 2, Value: 2}}, 1},
		{"minute above range", []Observation{{Minute: 1, Value: 1}, {Minute: 1440, Value: 2}}, 1},
		{"duplicate", []Observation{{Minute: 1, Value: 1}, {Minute: 1, Value: 2}}, 1},
		{"descending", []Observation{{Minute: 2, Value: 1}, {Minute: 1, Value: 2}}, 1},
		{"nan", []Observation{{Minute: 1, Value: math.NaN()}, {Minute: 2, Value: 2}}, 1},
		{"positive infinity", []Observation{{Minute: 1, Value: 1}, {Minute: 2, Value: math.Inf(1)}}, 1},
		{"negative infinity", []Observation{{Minute: 1, Value: 1}, {Minute: 2, Value: math.Inf(-1)}}, 1},
		{"before first", []Observation{{Minute: 10, Value: 1}, {Minute: 20, Value: 2}}, 9},
		{"after last", []Observation{{Minute: 10, Value: 1}, {Minute: 20, Value: 2}}, 21},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := InterpolateObservation(tc.in, tc.at)
			if err == nil || got != 0 {
				t.Fatalf("got %v, %v; want zero and error", got, err)
			}
		})
	}
}

func TestInterpolateObservationValidatesPastExactMatch(t *testing.T) {
	in := []Observation{{Minute: 1, Value: 10}, {Minute: 2, Value: 20}, {Minute: 2, Value: 30}}
	if got, err := InterpolateObservation(in, 1); err == nil || got != 0 {
		t.Fatalf("exact early match bypassed complete validation: %v, %v", got, err)
	}
}

package solution

import (
    "math"
    "testing"
)

func TestReviewFiniteMidpoint0027(t *testing.T) {
    got, err := InterpolateObservation([]Observation{{Minute: 0, Value: -1e308}, {Minute: 2, Value: 1e308}}, 1)
    if err != nil || math.IsNaN(got) || math.IsInf(got, 0) || got != 0 {
        t.Fatalf("representable midpoint: got %v, error %v; want 0", got, err)
    }
}

