package solution

import (
	"errors"
	"math"
)

type Observation struct {
	Minute int
	Value  float64
}

func InterpolateObservation(observations []Observation, minute int) (float64, error) {
	if len(observations) < 2 {
		return 0, errors.New("at least two observations are required")
	}
	if minute < 0 || minute > 1439 {
		return 0, errors.New("requested minute is out of range")
	}
	for i, observation := range observations {
		if observation.Minute < 0 || observation.Minute > 1439 {
			return 0, errors.New("observation minute is out of range")
		}
		if math.IsNaN(observation.Value) || math.IsInf(observation.Value, 0) {
			return 0, errors.New("observation value is not finite")
		}
		if i > 0 && observations[i-1].Minute >= observation.Minute {
			return 0, errors.New("observations are not strictly ordered")
		}
	}
	if minute < observations[0].Minute || minute > observations[len(observations)-1].Minute {
		return 0, errors.New("requested minute is outside the observations")
	}
	for i, observation := range observations {
		if minute == observation.Minute {
			return observation.Value, nil
		}
		if minute < observation.Minute {
			left := observations[i-1]
			fraction := float64((minute - left.Minute) / (observation.Minute - left.Minute))
			return left.Value + fraction*(observation.Value-left.Value), nil
		}
	}
	return observations[len(observations)-1].Value, nil
}

